import React from "react";

const Form = () => {
  const handleForm = () => {
    console.log("Handle form change");
  };

  const handleClick = () => {
    alert("Handle button click");
  };
  return (
    <div onS>
      <h2>Typical form</h2>
      <input type="text" onChange={handleForm} />
      <button onClick={handleClick}>Click me</button>
    </div>
  );
};

export default Form;
